-- Shipped inside plans-core (classpath:plans/db/migration). The migrateDatabase Lambda and the tests apply it with Flyway.
-- Never edit a released migration; add V2__..., V3__... files instead.

CREATE TABLE plan_instructions (
    -- UUIDv7 generated by the application (see UuidV7Generator). Its first 48 bits are the
    -- creation time in milliseconds, so ORDER BY plan_id follows created_at.
    plan_id    UUID          PRIMARY KEY,
    payload    JSONB         NOT NULL,   -- the whole PlanInstructions record
    created_at TIMESTAMP(3)  NOT NULL,   -- UTC, same millisecond as the timestamp inside plan_id
    updated_at TIMESTAMP(3)  NOT NULL,   -- UTC
    version    BIGINT        NOT NULL DEFAULT 0,
    CONSTRAINT chk_plan_instructions_status
        CHECK (payload ->> 'planStatus' IN ('ACTIVE', 'PAUSED', 'CANCELLED'))
);

-- lookup(userId, planType) and search by user
CREATE INDEX idx_plan_instructions_user_type
    ON plan_instructions ((payload ->> 'userId'), (payload ->> 'planType'));
-- search by status
CREATE INDEX idx_plan_instructions_status
    ON plan_instructions ((payload ->> 'planStatus'));
-- search by account numbers
CREATE INDEX idx_plan_instructions_dda_acc
    ON plan_instructions ((payload -> 'ddaAccInfo' ->> 'ddaAccNum'));
CREATE INDEX idx_plan_instructions_inv_acc
    ON plan_instructions ((payload -> 'invAccInfo' ->> 'invAccNum'));
